entries[171058] = { ["name"] = "Technik: Geätztes Gefäß des unheimlichen Kämpfers", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein geätztes Gefäß des unheimlichen Kämpfers effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines geätzten Gefäßes des unheimlichen Kämpfers.\nBenötigt Inschriftenkunde von Kul Tiras (1)\nVerkaufspreis:\nAllianz\nGeätztes Gefäß des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+10 Intelligenz\n+5 Ausdauer\nVerkaufspreis:\nHorde\nGeätztes Gefäß des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+10 Intelligenz\n+5 Ausdauer\nVerkaufspreis:\nBenötigt Leichtes Pergament (50), Tiefrote Tinte (50), Ultramarinblaue Tinte (10), Expulsom (3)" }
