entries[171265] = { ["name"] = "REUSE ME", ["text"] = "Benutzen: Bewahrt den Trinkenden davor, entdeckt zu werden, solange er stillsteht. Hält 20 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171266] = { ["name"] = "Trank des versteckten Geistes", ["text"] = "Benutzen: Gewährt dem Trinkenden 18 Sek. lang Unsichtbarkeit. Kann nicht von Spielercharakteren über Stufe 60 verwendet werden. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171267] = { ["name"] = "Spiritueller Heiltrank", ["text"] = "Benutzen: Stellt 36000 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171268] = { ["name"] = "Spiritueller Manatrank", ["text"] = "Benutzen: Stellt 21600 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171269] = { ["name"] = "Spiritueller Verjüngungstrank", ["text"] = "Benutzen: Stellt 36000 Gesundheit und 9000 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171270] = { ["name"] = "Trank der Spektralbeweglichkeit", ["text"] = "Benutzen: Erhöht Eure Beweglichkeit 25 Sek. lang um 516 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171271] = { ["name"] = "Trank der verhärteten Schatten", ["text"] = "Benutzen: Verleiht Eurem Körper widerstandfähige Energie, die Eure Rüstung 25 Sek. lang um 747 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171272] = { ["name"] = "Trank der geistigen Klarheit", ["text"] = "Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu 36000 Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171273] = { ["name"] = "Trank der Spektralintelligenz", ["text"] = "Benutzen: Erhöht Eure Intelligenz 25 Sek. lang um 516 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171274] = { ["name"] = "Trank der Spektralausdauer", ["text"] = "Benutzen: Erhöht Eure Ausdauer 25 Sek. lang um 775 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171275] = { ["name"] = "Trank der Spektralstärke", ["text"] = "Benutzen: Erhöht Eure Stärke 25 Sek. lang um 516 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171276] = { ["name"] = "Spektralfläschchen der Macht", ["text"] = "Benutzen: Erhöht den Primärwert 1 Stunde lang um 190 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[171278] = { ["name"] = "Spektralfläschchen der Ausdauer", ["text"] = "Benutzen: Erhöht die Ausdauer 1 Stunde lang um 285 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[171280] = { ["name"] = "Ewiges Fläschchen", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Gildenfläschchen (1)\nBenutzen: Gewährt den Effekt eines Fläschchens basierend auf Eurer Klasse und Euren Talenten. Hält 1 Stunde lang und über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[171281] = { ["name"] = "Ewiger Kessel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel enthält 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:" }
entries[171282] = { ["name"] = "Ewiger Kessel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel enthält 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:" }
entries[171283] = { ["name"] = "Ewiger Kessel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel enthält 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:" }
entries[171284] = { ["name"] = "Ewiger Kessel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Dieser Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:" }
entries[171285] = { ["name"] = "Schattenkernöl", ["text"] = "Benutzen: Gewährt Euch bei Anwendung auf eine Waffe für die nächsten 60 Min. eine hohe Chance, zusätzlich 881 Schattenschaden zu verursachen, wenn Ihr einem Gegner Schaden zufügt. (5 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[171286] = { ["name"] = "Einbalsamieröl", ["text"] = "Benutzen: Gewährt Euch bei Anwendung auf eine Waffe für die nächsten 60 Min. eine hohe Chance, Euch um 1322 Gesundheit zu heilen, wenn Ihr Schaden verursacht oder Heilung hervorruft. Bei vollständiger Gesundheit erhaltet Ihr stattdessen einen Schild, der 1322 Schaden absorbiert. (5 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[171287] = { ["name"] = "Gemahlene Todesblüte", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[171288] = { ["name"] = "Gemahlene Wachtfackel", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[171289] = { ["name"] = "Gemahlene Witwenblüte", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[171290] = { ["name"] = "Gemahlene Markwurzel", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[171291] = { ["name"] = "Gemahlener Ruhmesstieg", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[171292] = { ["name"] = "Gemahlener Nachtschatten", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[171293] = { ["name"] = "Beutel des Alchemisten", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Fläschcheneffekte halten länger\n\"Ein optionales Reagenz, das bei der Herstellung eines Rüstungsteils benutzt werden kann, um die Dauer von Fläschcheneffekten zu verlängern.\"\nVerkaufspreis:" }
entries[171301] = { ["name"] = "Spirituelles Gegengift", ["text"] = "Benutzen: Heilt Gifte bis Stufe 49 und verringert die Wirkungsdauer nachfolgender Gifte 2 Min. lang um 50%. Kann nicht in Instanzen verwendet werden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[171305] = { ["name"] = "Geborgene Truhe mit Vorräten", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[171310] = { ["name"] = "Ring der steingebundenen Kontrolle", ["text"] = "Wird beim Aufheben gebunden\n\"Die Steinhüter von Revendreth verwenden ihn, um inaktive Steinpirscher aufzuwecken.\"" }
entries[171312] = { ["name"] = "Rezept: Leerenfokus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Leerenfokus erschafft, einen außerweltlichen Kristall, der die Macht von N'Zoth nutzt, um mächtige Rüstungsteile herzustellen.\n\"Dunkle Runen huschen über die Schriftrolle, verändern sich stetig und nehmen immer unheimlichere Formen an.\"" }
entries[171313] = { ["name"] = "Bauplan: A-N0M-AL-3 zahnradgetriebene Schutzbrille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nStellt eine A-N0M-AL-3 zahnradgetriebene Schutzbrille her.\nBenötigt Ingenieurskunst von Kul Tiras (165)\n\"Lehrt Euch, wie man eine A-N0M-AL-3 zahnradgetriebene Schutzbrille herstellt.\"" }
entries[171314] = { ["name"] = "Bauplan: Synthetische A-N0M-AL-3 Augengläser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nStellt synthetische A-N0M-AL-3 Augengläser her.\nBenötigt Ingenieurskunst von Kul Tiras (165)\n\"Lehrt Euch, wie man synthetische A-N0M-AL-3 Augengläser herstellt.\"" }
entries[171315] = { ["name"] = "Nachtschatten", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[171316] = { ["name"] = "Pläne: Verstörende Osmenitbeinschützer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nStellt verstörende Osmenitbeinschützer her.\nBenötigt Schmiedekunst von Kul Tiras (165)\n\"Lehrt Euch, wie man verstörende Osmenitbeinschützer herstellt.\"" }
entries[171317] = { ["name"] = "Pläne: Verstörende Osmenitgürtung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nStellt eine verstörende Osmenitgürtung her.\nBenötigt Schmiedekunst von Kul Tiras (165)\n\"Lehrt Euch, wie man eine verstörende Osmenitgürtung herstellt.\"" }
entries[171318] = { ["name"] = "Rezept: Entfesselter Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen entfesselten Alchemistenstein herstellt.\nStellt einen entfesselten Alchemistenstein her.\nBenötigt Alchemie von Kul Tiras\n(165)\n\nEntfesselter Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\n+ 12 Vielseitigkeit\n\nPrismatischer Sockel\n\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 31 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Kul Tiras\n(165)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Zin'anthide (175), Ankerkraut (60), Expulsom (30)" }
entries[171320] = { ["name"] = "Leerenfokus", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Dieser dunkle Kristall basiert auf einem bei N'Zoths Truppen erbeuteten Konzept. Die Energie, die er ausstrahlt, ermöglicht es dem Träger, mächtige Gegenstände herzustellen.\"" }
entries[171323] = { ["name"] = "Spiritueller Alchemiestein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 25 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 67 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Schattenlande\n(100)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
