entries[171334] = { ["name"] = "Leerenberührter Stoff", ["text"] = "Wird beim Aufheben gebunden\n\"Das Material, aus dem die Rüstung der Armee aus der Vision besteht. Furorion hat vielleicht Verwendung dafür.\"\nVerkaufspreis:" }
entries[171335] = { ["name"] = "Verderbender Kern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: [Erhöht den Verderbniswiderstand von Ashjra'kamas um weitere 3.][Ermächtigt Ashjra'kamas, Tuch der Entschlossenheit, und erhöht seine Widerstandskraft gegen den Entzug geistiger Gesundheit und gegen Verderbnis.]" }
entries[171337] = { ["name"] = "Wollige Wendigofäustlinge", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHände Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
