entries[171339] = { ["name"] = "Wollige Wendigoschlabberhosen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBeine Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
