entries[171341] = { ["name"] = "Wolliger Wendigopulli", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[171343] = { ["name"] = "Leeres Pergament", ["text"] = "Questgegenstand\n\"Wurde vor dem Schicksal gerettet, mit langatmigen und wortreichen Forschungsnotizen beschrieben zu werden.\"" }
entries[171344] = { ["name"] = "Venthyrkalligraphieset", ["text"] = "Questgegenstand\nEinzigartig\n\"Kein Venthyrdokument ist gültig, bevor es über alle Maßen verziert wurde.\"" }
entries[171345] = { ["name"] = "Gefälschter Verurteilungsbrief", ["text"] = "Questgegenstand\nEinzigartig\n\"In Sachen Wortwahl und Formatierung musstet Ihr etwas raten, aber er sieht dennoch recht überzeugend aus.\"" }
entries[171346] = { ["name"] = "Briefe aus der Stadt", ["text"] = "\"Voller Tratsch über Adelige und Gerüchte über die Rebellion.\"\nVerkaufspreis:" }
entries[171347] = { ["name"] = "Verderbtes Knochenfragment", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Segment des Gesichtslosenskeletts. Furorion hat vielleicht Verwendung dafür.\"\nVerkaufspreis:" }
entries[171348] = { ["name"] = "Zerrissene Rolle der unweltlichen Rituale", ["text"] = "\"Die Wörter verschwimmen vor Euren Augen, sodass es schwierig ist, die fremdartigen Zauberformeln zu verstehen.\"\nVerkaufspreis:" }
entries[171349] = { ["name"] = "Trank des Phantomfeuers", ["text"] = "Benutzen: Eure Angriffe und Zauber haben eine Chance, eine feurige Projektion zum Ziel zu schicken, die ihm 6270 Schattenflammenschaden zufügt.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, wird der zusätzliche Schaden um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171350] = { ["name"] = "Trank des göttlichen Erwachens", ["text"] = "Benutzen: Eure Heilzauber heilen abhängig von der fehlenden Gesundheit des Ziels um bis zu 11765 Gesundheit mehr.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Einbalsamieröl verstärkt ist, wird die zusätzliche Heilung um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171351] = { ["name"] = "Trank der tödlichen Fixierung", ["text"] = "Benutzen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, Euer Ziel mit 'Tödliche Fixierung' zu belegen, was im Verlauf von 8 Sek. 172 Schattenschaden verursacht und bis zu 5-mal stapelbar ist. Beim Erreichen von 5 Stapeln explodiert 'Tödliche Fixierung' und fügt dem Ziel 3946 Schattenschaden zu.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, wird der Explosionsschaden um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171352] = { ["name"] = "Trank des ermächtigten Exorzismus", ["text"] = "Benutzen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, die Anima des Ziels ausbrechen zu lassen, was allen Gegnern innerhalb von 10 Metern um das Ziel bis zu 3740 Schattenschaden zufügt.\n\nWenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, werden der zusätzliche Schaden und die Reichweite um 20% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[171353] = { ["name"] = "Ausgerissene Seite von \"Der Fluch des Steins\"", ["text"] = "Questgegenstand\n\"Die auf der Seite festgehaltenen Worte und Bilder sind ziemlich verstörend.\"" }
entries[171354] = { ["name"] = "Schrecklicher Kern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: [Erhöht den Verderbniswiderstand von Ashjra'kamas um weitere 3.][Ermächtigt Ashjra'kamas, Tuch der Entschlossenheit, und erhöht seine Widerstandskraft gegen den Entzug geistiger Gesundheit und gegen Verderbnis.]" }
entries[171355] = { ["name"] = "Leerengeborener Kern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: [Erhöht den Verderbniswiderstand von Ashjra'kamas um weitere 3.][Ermächtigt Ashjra'kamas, Tuch der Entschlossenheit, und erhöht seine Widerstandskraft gegen den Entzug geistiger Gesundheit und gegen Verderbnis.]" }
entries[171356] = { ["name"] = "Vergrößerungstotem", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert ein Vergrößerungstotem, um Gegner in der Nähe zu vergrößern. (5 Sek. Abklingzeit)" }
entries[171357] = { ["name"] = "Worgfleisch", ["text"] = "Questgegenstand\n\"Hat einen herzhaften Geschmack.\"" }
entries[171358] = { ["name"] = "Gluckenhäppchen", ["text"] = "Questgegenstand\n\"Fast nur die besten Stücke.\"" }
entries[171361] = { ["name"] = "Wappenrock des berühmten Forschers", ["text"] = "Wappenrock" }
entries[171363] = { ["name"] = "Illusion: Stechende Sande", ["text"] = "Benutzen: Sammelt die Waffenillusionsvorlage 'Stechende Sande'.\nVerkaufspreis:" }
entries[171364] = { ["name"] = "Dunkelmond-Zylinder", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht gewonnene Erfahrung und Ruf 1 Stunde lang um 10%. Der Hut wird dabei verbraucht.\nBenötigt Dunkelmond-Jahrmarkt\nVerkaufspreis:" }
entries[171365] = { ["name"] = "Verkleidung", ["text"] = "Questgegenstand\nBenutzen: Zieht eine Verkleidung an.\n\"Diese Verkleidung hält keiner näheren Untersuchung stand.\"" }
entries[171367] = { ["name"] = "Tonhammer", ["text"] = "Questgegenstand\n\"Ein magisches Harmoniewerkzeug für die uralten Glocken der Bastion.\"" }
entries[171368] = { ["name"] = "Tonreine Legierung", ["text"] = "Questgegenstand\nEinzigartig (30)\nBenutzen: Kombiniert 20 Stück tonreine Legierung und 3 Stück singendes Holz, um einen Tonhammer zu erschaffen.\n\"Erzeugt einen klaren, angenehmen Ton, wenn man sie anschlägt.\"" }
entries[171369] = { ["name"] = "Singendes Holz", ["text"] = "Questgegenstand\nEinzigartig (3)\nBenutzen: Kombiniert 20 Stück tonreine Legierung und 3 Stück singendes Holz, um einen Tonhammer zu erschaffen.\n\"Teil einer Pflanze, die sanfte Töne erzeugt, wenn der Wind über sie hinwegweht.\"" }
entries[171370] = { ["name"] = "Trank der Gespensterschnelligkeit", ["text"] = "Benutzen: Erhöht Eure Bewegungsgeschwindigkeit als Geist um 100%. Kann nur in den Schattenlanden benutzt werden. Hält 2 Min. lang an. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[171372] = { ["name"] = "Ehrenabzeichen des Alteractals", ["text"] = "Wird beim Aufheben gebunden\n\"Kann gegen Belohnungen für die Teilnahme am klassischen Alteractal eingetauscht werden.\"\nVerkaufspreis:" }
entries[171373] = { ["name"] = "Besinnung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft den Speer, um ein Eliteziel zu schwächen. (12 Sek. Abklingzeit)\n\"Dieser Speer ist mehr als nur eine Waffe. Er kann durch den Kern einer Seele schneiden und so tief verborgene Erinnerungen und Emotionen offenlegen.\"" }
