entries[172009] = { ["name"] = "Technik: Vertrag: Rajani", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Vertrag: Rajani herstellt.\nStellt einen Vertrag: Rajani her.\nBenötigt Inschriftenkunde von Kul Tiras (165)\nBenötigt Rajani\n- Respektvoll\nVerkaufspreis:\nVertrag: Rajani\nBenutzen: Schließt einen Vertrag mit den Rajani ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in Kul Tiras oder Zandalar abschließt.\nBenötigt Rajani\n- Freundlich\nVerkaufspreis:\nBenötigt Leichtes Pergament , Ultramarinblaue Tinte (25)" }
