entries[172011] = { ["name"] = "Technik: Vertrag: Abkommen von Uldum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Vertrag: Abkommen von Uldum herstellt.\nStellt einen Vertrag: Abkommen von Uldum her.\nBenötigt Inschriftenkunde von Kul Tiras (165)\nBenötigt Abkommen von Uldum\n- Respektvoll\nVerkaufspreis:\nVertrag: Abkommen von Uldum\nBenutzen: Schließt einen Vertrag mit dem Abkommen von Uldum ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in Kul Tiras oder Zandalar abschließt.\nBenötigt Abkommen von Uldum\n- Freundlich\nVerkaufspreis:\nBenötigt Leichtes Pergament , Ultramarinblaue Tinte (25)" }
entries[172012] = { ["name"] = "Obsidianweltenbrecher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ich hatte im Laufe der Geschichte schon viele Namen. Und jeder von ihnen versetzte die Welt in Schrecken: Neltharion, Xaxas und viele mehr. Aber Ihr sollt mich unter dem Namen Todesschwinge kennen, denn das ist es, was ich bin! Ich bin das Verderben allen Lebens, die Dunkelheit in der Geschichte, der Herr des Todes, der Meister der Zerstörung. Und ich sage Euch, so wahr ich hier spreche, diese Welt gehört mir!\" - Neltharion der Erdwächter\nErfolg:\nErinnerungen von Feuer, Eis und Dämonen\nKategorie:\nEreignisse" }
