entries[172022] = { ["name"] = "Kampfwidder der Sturmlanzen", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\n\n\"Vom Sturmlanzenklan im Alteracgebirge dazu aufgezogen, Orcs Kopfstöße zu verpassen.\"\nErfolg:\nDas Alte-ractal\nKategorie:\nAlteractal" }
entries[172023] = { ["name"] = "Frostwolfknurrer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\n\n\"Wurde vom Frostwolfklan im Alteracgebirge aufgezogen und darauf abgerichtet, Zwerge zu beißen.\"\nErfolg:\nDas Alte-ractal\nKategorie:\nAlteractal" }
entries[172024] = { ["name"] = "Uralte Maldrazitwaffe", ["text"] = "Questgegenstand\n\"Der in die Waffe eingelassene Kristall leuchtet schwach.\"" }
entries[172035] = { ["name"] = "Herz von Tirna Rowen", ["text"] = "Questgegenstand\nEinzigartig\n\"Geschwächt und ausgelaugt. Enthält aber immer noch einen Funken Anima.\"" }
entries[172036] = { ["name"] = "Kalas Sabberball", ["text"] = "Questgegenstand\n\"Immer noch ein bisschen feucht. Fasziniert Larions jeder Altersklasse.\"" }
entries[172037] = { ["name"] = "Herr Mikanikos", ["text"] = "Questgegenstand\n\"Der Quietscher wurde schon vor Ewigkeiten herausgerissen, aber er ist immer noch hilfreich. Nach Kalas Lieblingsprovosten benannt.\"" }
entries[172038] = { ["name"] = "Düstereisenfesseln", ["text"] = "Benutzen: Schärft Eure Klingenwaffe und erhöht so 1 Stunde lang den kritischen Nahkampftrefferwert um 12. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[172039] = { ["name"] = "Gemütliches Kuschelkissen", ["text"] = "Questgegenstand\n\"Kala hat es, seit sie ein Jungtier war, und kann ohne es nicht schlafen.\"" }
